const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '₹'+Number(n).toLocaleString('en-IN');
const seed={leads:[{id:101,name:'Priya Sharma',city:'Bangalore',area:'Whitefield',service:'Deep cleaning',property:'3 BHK · Furnished',amount:6499,status:'New enquiry',source:'Website',owner:'Ananya',phone:'Demo contact',note:'Moving in next week. Prefers a morning slot.'},{id:102,name:'Rahul Desai',city:'Bangalore',area:'Indiranagar',service:'Pest control',property:'2 BHK · Cockroaches',amount:2499,status:'Contacted',source:'WhatsApp',owner:'Ananya',phone:'Demo contact',note:'Call after 4 PM to confirm availability.'},{id:104,name:'Arjun Rao',city:'Hassan',area:'Vidyanagar',service:'Deep cleaning',property:'4 BHK · Empty villa',amount:8999,status:'New enquiry',source:'Phone',owner:'Kiran',phone:'Demo contact',note:'Needs a weekend appointment.'},{id:105,name:'Sneha Patel',city:'Bangalore',area:'HSR Layout',service:'Pest control',property:'3 BHK · Termites',amount:7999,status:'Quotation sent',source:'Website',owner:'Ananya',phone:'Demo contact',note:'Include a follow-up inspection.'},{id:106,name:'Vikram Shetty',city:'Bangalore',area:'JP Nagar',service:'Deep cleaning',property:'2 BHK · Furnished',amount:4999,status:'Contacted',source:'Referral',owner:'Ananya',phone:'Demo contact',note:'Kitchen needs extra attention.'}],jobs:[{id:2401,name:'Aditi Menon',city:'Bangalore',area:'Whitefield',service:'Deep cleaning',property:'3 BHK · Furnished',amount:6499,paid:2000,status:'In progress',team:'Team A · Ravi',date:'2026-09-13',time:'09:00',checks:[]},{id:2402,name:'Rohan Mehta',city:'Bangalore',area:'Koramangala',service:'Pest control',property:'2 BHK · General treatment',amount:2499,paid:2499,status:'Completed',team:'Team B · Suresh',date:'2026-09-13',time:'10:30',checks:[0,1,2]},{id:2404,name:'Nikhil Gowda',city:'Bangalore',area:'HSR Layout',service:'Deep cleaning',property:'2 BHK · Empty flat',amount:4999,paid:1500,status:'Scheduled',team:'Unassigned',date:'2026-09-13',time:'14:00',checks:[]},{id:2405,name:'Divya Hegde',city:'Hassan',area:'Kuvempu Nagar',service:'Pest control',property:'3 BHK · Termite inspection',amount:7999,paid:2000,status:'Scheduled',team:'Team D · Deepak',date:'2026-09-14',time:'09:00',checks:[]},{id:2406,name:'Sanjay Kumar',city:'Bangalore',area:'JP Nagar',service:'Deep cleaning',property:'4 BHK · Villa',amount:8999,paid:8999,status:'Completed',team:'Team A · Ravi',date:'2026-09-12',time:'09:00',checks:[0,1,2]}],tickets:[{id:301,name:'Sanjay Kumar',job:2406,issue:'Window cleaning touch-up requested',status:'Open',priority:'Medium'},{id:302,name:'Rohan Mehta',job:2402,issue:'Schedule post-treatment follow-up',status:'In progress',priority:'Low'}],activity:['Rohan Mehta’s pest control service completed','New enquiry from Priya Sharma · Website','Team A checked in at Whitefield']};
let db;try{db=JSON.parse(localStorage.getItem('vucare-demo-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}
// Keep existing browser data while removing discontinued service records.
const supportedServices = new Set(['Deep cleaning','Pest control']);
db.leads = db.leads.filter(record => supportedServices.has(record.service));
db.jobs = db.jobs.filter(record => supportedServices.has(record.service));
db.tickets = db.tickets.filter(ticket => db.jobs.some(job => job.id === ticket.job));
db.activity = db.activity.filter(entry => !/paint|Meera Nair|Lakshmi Iyer/i.test(entry));
try { localStorage.setItem('vucare-demo-v1', JSON.stringify(db)); } catch {}
let role='Admin',page='overview',query='',city='All cities';
const access={Admin:['overview','leads','bookings','customers','schedule','payments','support','reports'],Sales:['overview','leads','customers','bookings'],Operations:['overview','bookings','schedule','customers','support'],'Field Staff':['overview','schedule'],Accounts:['overview','payments','customers','reports'],Support:['overview','customers','bookings','support']};
const names={overview:['◫','Overview'],leads:['◷','Leads & follow-ups'],bookings:['▤','Bookings'],customers:['♧','Customers'],schedule:['▦','Team schedule'],payments:['▣','Payments'],support:['◉','Support & revisits'],reports:['▥','Reports']};
function save(message){try{localStorage.setItem('vucare-demo-v1',JSON.stringify(db))}catch{toast('Browser storage unavailable; changes last for this session.')}if(message){db.activity.unshift(message);db.activity=db.activity.slice(0,6);try{localStorage.setItem('vucare-demo-v1',JSON.stringify(db))}catch{}toast(message)}render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function jobs(){return db.jobs.filter(j=>(role!=='Field Staff'||j.team==='Team A · Ravi')&&(city==='All cities'||j.city===city))}
function leads(){return db.leads.filter(l=>(role!=='Sales'||l.owner==='Ananya')&&(city==='All cities'||l.city===city))}
function badge(s){const c=['Completed','Paid','Converted','Resolved'].includes(s)?'green':['New enquiry','Scheduled','Open','Unassigned'].includes(s)?'orange':['In progress','Contacted','Part paid'].includes(s)?'blue':s==='Quotation sent'?'purple':'';return `<span class="badge ${c}">${esc(s)}</span>`}
function initials(n){return n.split(' ').map(x=>x[0]).slice(0,2).join('')}
function person(j){return `<div class="customer-cell"><span class="avatar">${initials(j.name)}</span><div><strong>${esc(j.name)}</strong><small>${esc(j.area)}, ${esc(j.city)}</small></div></div>`}
function pageHeading(title,sub,action=''){return `<div class="page-top"><div><p class="eyebrow">VU CARE / ${role.toUpperCase()}</p><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${action}</div></div>`}
function stat(label,value,note,icon){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`}
function citySelect(){return `<select id="city" aria-label="Filter by city">${['All cities','Bangalore','Mysore','Hassan'].map(x=>`<option ${x===city?'selected':''}>${x}</option>`).join('')}</select>`}
function go(p){if(!access[role].includes(p))return;page=p;query='';location.hash=p;render();document.body.classList.remove('nav-open')}
function render(){if(!access[role].includes(page))page=access[role][0];$('#nav').innerHTML=access[role].map(p=>`<a href="#${p}" class="${page===p?'active':''}" data-nav="${p}"><i>${names[p][0]}</i>${names[p][1]}</a>`).join('');$('#crumb').textContent=names[page][1];$('#profile-name').innerHTML=`${role==='Field Staff'?'Ravi · Team A':'Ananya Kumar'}<small>${esc(role)} · Demo view</small>`;$('#main').innerHTML=({overview,leads:leadPage,bookings:bookingPage,customers:customerPage,schedule:schedulePage,payments:paymentPage,support:supportPage,reports:reportPage}[page])();}
function overview(){const js=jobs(),ls=leads(),total=js.reduce((s,j)=>s+j.paid,0),due=js.reduce((s,j)=>s+j.amount-j.paid,0);const today=js.filter(j=>j.date==='2026-09-13');let stats=role==='Field Staff'?stat('Assigned jobs',js.length,'Team A · Ravi','▦')+stat('Today’s visits',today.length,'13 September 2026','◷')+stat('In progress',js.filter(j=>j.status==='In progress').length,'Currently on site','◉')+stat('Completed',js.filter(j=>j.status==='Completed').length,'Ready for review','✓'):stat('Active enquiries',ls.filter(l=>l.status!=='Converted').length,'<b>'+ls.filter(l=>l.status==='New enquiry').length+' new</b> awaiting first contact','♧')+stat('Today’s jobs',today.length,`<b>${today.filter(j=>j.status==='Completed').length} completed</b> · ${today.filter(j=>j.status!=='Completed').length} remaining`,'▦')+stat('Payments collected',money(total),'Across the demo bookings','↗')+stat('Outstanding balance',money(due),`${js.filter(j=>j.paid<j.amount).length} bookings with balance due`,'▣');return pageHeading(role==='Field Staff'?'Your day, at a glance.':'Good morning, Ananya ☀','Here’s what’s happening at Vu Care today.',citySelect()+(role==='Admin'||role==='Sales'?'<button class="primary" data-action="new-lead">＋ New enquiry</button>':''))+`<div class="stats">${stats}</div>`+(role==='Field Staff'?jobCards(js):`<div class="grid"><section class="card"><div class="card-head"><div><h2>Booking value by service</h2><p>Sample bookings · September 2026</p></div><div class="legend"><span><em></em>Value</span><span><em class="light"></em>Collected</span></div></div><div class="chart-total"><strong>${money(js.reduce((s,j)=>s+j.amount,0))}</strong><span>${js.length} service bookings</span></div><div class="chart">${['Deep cleaning','Pest control'].map(s=>{let v=js.filter(j=>j.service===s).reduce((a,j)=>a+j.amount,0),p=js.filter(j=>j.service===s).reduce((a,j)=>a+j.paid,0);let max=Math.max(1,...['Deep cleaning','Pest control'].map(t=>js.filter(j=>j.service===t).reduce((a,j)=>a+j.amount,0)));return `<div class="bar-group" style="width:95px"><div class="bar" style="height:${v/max*95}%" title="${esc(s)}: ${money(v)}"></div><div class="bar light" style="height:${p/max*95}%" title="Collected: ${money(p)}"></div><small>${s}</small></div>`}).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Service mix</h2><p>Where your teams are making a difference</p></div><span>◌</span></div>${['Deep cleaning','Pest control'].map((s,i)=>{const count=js.filter(j=>j.service===s).length;return `<div class="service-row"><div class="service-line"><span>${s}</span><b>${count} bookings</b></div><div class="track"><span style="width:${count/Math.max(js.length,1)*100}%;background:${['#2d7260','#a9c47d','#d5af6d'][i]}"></span></div></div>`}).join('')}<div class="service-note"><span>Across ${new Set(js.map(j=>j.city)).size} cities</span><strong>${js.length} total bookings</strong></div></section></div><div class="grid"><section class="card"><div class="card-head"><div><h2>Today’s service visits</h2><p>Sunday, 13 September</p></div><button class="text-button" data-nav="${access[role].includes('schedule')?'schedule':'bookings'}">View all →</button></div>${jobTable(today,true)}<div class="table-footer">${today.filter(j=>j.team==='Unassigned').length} booking needs a crew assignment</div></section><div><section class="card"><div class="card-head"><h2>Recent activity</h2><span class="badge">Demo</span></div><div class="activity">${db.activity.slice(0,3).map((a,i)=>`<div class="activity-item"><span class="activity-icon">${['✓','＋','↗'][i]}</span><div><p>${esc(a)}</p><small>${i===0?'Latest update':'Earlier in this demo'}</small></div></div>`).join('')}</div></section><div class="callout"><h3>${role==='Accounts'?'Keep collections on track':'A little follow-up goes a long way.'}</h3><p>${role==='Accounts'?`${money(due)} is awaiting collection.`:`${ls.filter(l=>l.status==='Quotation sent').length} quotations are waiting for a customer decision.`}</p><button data-nav="${access[role].includes('leads')?'leads':access[role].includes('payments')?'payments':'support'}">${access[role].includes('leads')?'Review follow-ups':'Open workspace'} →</button></div></div></div>`)}
function jobTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>SERVICE</th>${compact?'':'<th>DATE / TEAM</th>'}<th>STATUS</th><th></th></tr></thead><tbody>${list.map(j=>`<tr><td>${person(j)}</td><td>${esc(j.service)}<small>${compact?j.time:j.property}</small></td>${compact?'':`<td>${esc(j.date)} · ${esc(j.time)}<small>${esc(j.team)}</small></td>`}<td>${badge(j.status)}</td><td><button class="text-button" data-job="${j.id}" aria-label="Open booking ${j.id}">↗</button></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No bookings match this view.</div>':''}</div>`}
function leadPage(){const list=leads().filter(l=>(l.name+' '+l.service+' '+l.area).toLowerCase().includes(query.toLowerCase()));return pageHeading('Every enquiry, an opportunity.','Track conversations and turn enquiries into booked services.','<button class="primary" data-action="new-lead">＋ New enquiry</button>')+`<div class="filters" style="padding:0 0 22px;border:0"><input class="search" id="search" placeholder="Search customer, service or area…" value="${esc(query)}" aria-label="Search leads">${citySelect()}</div><div class="board">${['New enquiry','Contacted','Quotation sent','Converted'].map(s=>`<section class="column"><h2>${s}<span>${list.filter(l=>l.status===s).length}</span></h2>${list.filter(l=>l.status===s).map(l=>`<article class="lead-card" tabindex="0" role="button" data-lead="${l.id}">${badge(l.service)}<h3 style="margin-top:13px">${esc(l.name)}</h3><p>${esc(l.property)}</p><p>${esc(l.area)} · ${esc(l.city)}</p><div class="lead-bottom"><b>${money(l.amount)}</b><span>${esc(l.source)}</span></div></article>`).join('')||'<p class="sub" style="padding:15px 5px">No enquiries in this stage</p>'}</section>`).join('')}</div>`}
function bookingPage(){return pageHeading('Bookings','One place for every service, visit and customer.',citySelect())+`<section class="card"><div class="filters"><input class="search" id="search" placeholder="Search bookings…" value="${esc(query)}" aria-label="Search bookings"></div>${jobTable(jobs().filter(j=>(j.name+' '+j.service+' '+j.status).toLowerCase().includes(query.toLowerCase())))}</section>`}
function customers(){const seen=new Map();[...jobs(),...(role==='Accounts'?[]:leads())].forEach(j=>{if(!seen.has(j.name))seen.set(j.name,j)});return [...seen.values()]}
function customerPage(){let list=customers().filter(c=>(c.name+' '+c.city).toLowerCase().includes(query.toLowerCase()));return pageHeading('Customers','A complete picture of every customer relationship.',citySelect())+`<section class="card"><div class="filters"><input class="search" id="search" value="${esc(query)}" placeholder="Search customers…" aria-label="Search customers"></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>PROPERTY</th><th>SERVICE</th><th>RELATIONSHIP</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td>${person(c)}</td><td>${esc(c.property)}</td><td>${esc(c.service)}</td><td>${badge(db.jobs.some(j=>j.name===c.name)?'Customer':'Enquiry')}</td><td><button class="text-button" data-customer="${esc(c.name)}">View history →</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No customers found.</div>'}</div></section>`}
function jobCards(list){return `<div class="schedule">${list.map(j=>`<article class="card job-card"><div class="service-line"><b>${esc(j.time)} · ${esc(j.date.slice(5))}</b>${badge(j.status)}</div><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}</p><p>⌖ ${esc(j.area)}, ${esc(j.city)}</p><div class="service-note" style="padding:15px 0 0"><span>${esc(j.team)}</span><b>#VC-${j.id}</b></div><div class="actions"><button data-job="${j.id}" class="${role==='Field Staff'?'primary':''}">${role==='Field Staff'?'Open job checklist':'Manage booking'} →</button></div></article>`).join('')||'<div class="empty">No jobs assigned.</div>'}</div>`}
function schedulePage(){return pageHeading(role==='Field Staff'?'My service visits':'Team schedule',role==='Field Staff'?'Your assigned jobs, checklists and completion updates.':'Manage upcoming visits and keep every crew on track.',citySelect())+jobCards(jobs().slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}
function paymentPage(){const js=jobs();return pageHeading('Payments','Track advances, collections and outstanding balances.',citySelect())+`<div class="stats">${stat('Booking value',money(js.reduce((s,j)=>s+j.amount,0)),'All sample bookings','▤')}${stat('Collected',money(js.reduce((s,j)=>s+j.paid,0)),'Recorded payments','✓')}${stat('Outstanding',money(js.reduce((s,j)=>s+j.amount-j.paid,0)),'Balance to collect','◷')}${stat('Fully paid',js.filter(j=>j.amount===j.paid).length,'Bookings settled','▣')}</div><section class="card"><div class="card-head"><h2>Invoices & collections</h2></div><div class="table-wrap"><table><thead><tr><th>CUSTOMER / INVOICE</th><th>TOTAL</th><th>PAID</th><th>BALANCE</th><th>STATUS</th><th></th></tr></thead><tbody>${js.map(j=>`<tr><td><strong>${esc(j.name)}</strong><small>INV-${j.id}</small></td><td>${money(j.amount)}</td><td>${money(j.paid)}</td><td>${money(j.amount-j.paid)}</td><td>${badge(j.paid===j.amount?'Paid':j.paid?'Part paid':'Unpaid')}</td><td><button class="text-button" data-invoice="${j.id}">${j.paid<j.amount?'Record payment':'View invoice'} →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function supportPage(){return pageHeading('Support & revisits','Close the loop on customer feedback and follow-up visits.','<button class="primary" data-action="new-ticket">＋ New request</button>')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>REQUEST</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${db.tickets.map(t=>`<tr><td><strong>${esc(t.name)}</strong><small>Booking #VC-${t.job}</small></td><td>${esc(t.issue)}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td>${t.status==='Resolved'?'✓':`<button class="text-button" data-ticket="${t.id}">${t.status==='Open'?'Start review':'Resolve'} →</button>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function reportPage(){const js=jobs();return pageHeading('Business reports','A clear view of service performance across your cities.','<button data-action="export">↓ Export bookings CSV</button>')+`<div class="report-grid">${[['Revenue by city',['Bangalore','Mysore','Hassan'],'city'],['Revenue by service',['Deep cleaning','Pest control'],'service']].map(([t,vals,key])=>`<section class="card"><div class="card-head"><h2>${t}</h2></div>${vals.map(v=>`<div class="metric-row"><span>${v}</span><b>${money(js.filter(j=>j[key]===v).reduce((s,j)=>s+j.amount,0))}</b></div>`).join('')}</section>`).join('')}<section class="card"><div class="card-head"><h2>Job performance</h2></div>${['Scheduled','In progress','Completed'].map(s=>`<div class="metric-row">${badge(s)}<b>${js.filter(j=>j.status===s).length} bookings</b></div>`).join('')}</section><section class="card"><div class="card-head"><h2>Collections summary</h2></div><div class="metric-row"><span>Collected</span><b>${money(js.reduce((s,j)=>s+j.paid,0))}</b></div><div class="metric-row"><span>Outstanding</span><b>${money(js.reduce((s,j)=>s+j.amount-j.paid,0))}</b></div><div class="metric-row"><span>Collection rate</span><b>${Math.round(js.reduce((s,j)=>s+j.paid,0)/Math.max(1,js.reduce((s,j)=>s+j.amount,0))*100)}%</b></div></section></div>`}
function modal(title,body,footer=''){const d=$('#dialog');$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">✕</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;d.showModal()}
function options(a,v){return a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}
function newLead(){modal('New customer enquiry',`<form id="lead-form"><div class="modal-body form-grid"><label>Customer name<input name="name" required maxlength="70" placeholder="Full name"></label><label>Phone<input name="phone" required maxlength="30" placeholder="Contact number"></label><label>Service<select name="service">${options(['Deep cleaning','Pest control'])}</select></label><label>City<select name="city">${options(['Bangalore','Mysore','Hassan'])}</select></label><label>Area<input name="area" required placeholder="e.g. Whitefield" maxlength="70"></label><label>Property details<input name="property" required placeholder="e.g. 3 BHK, furnished" maxlength="100"></label><label>Estimated value (₹)<input name="amount" type="number" min="1" max="10000000" step="1" required value="6499"></label><label>Lead source<select name="source">${options(['Website','WhatsApp','Phone','Referral'])}</select></label><label class="full">Notes<textarea name="note" rows="2" maxlength="500"></textarea></label></div><div class="modal-footer"><button type="button" data-action="close">Cancel</button><button class="primary">Create enquiry</button></div></form>`)}
function leadDetail(id){let l=leads().find(l=>l.id===id);if(!l)return;modal(esc(l.name),`<div class="modal-body"><div class="detail-list"><div><small>Service</small>${esc(l.service)}</div><div><small>Estimated value</small>${money(l.amount)}</div><div><small>Property</small>${esc(l.property)}</div><div><small>Location</small>${esc(l.area)}, ${esc(l.city)}</div><div><small>Source</small>${esc(l.source)}</div><div><small>Contact</small>${esc(l.phone)}</div></div><p>${esc(l.note)}</p><label class="sub">Lead stage <select id="lead-stage">${options(['New enquiry','Contacted','Quotation sent'],l.status)}</select></label></div>`,l.status==='Converted'?'<button data-action="close">Close</button>':`<button data-save-lead="${id}">Save stage</button><button class="primary" data-convert="${id}">Convert to booking →</button>`)}
function jobDetail(id){let j=jobs().find(j=>j.id===id);if(!j)return;const canManage=['Admin','Operations'].includes(role),field=role==='Field Staff';modal(`Booking #VC-${j.id}`,`<div class="modal-body"><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}<br>${esc(j.area)}, ${esc(j.city)}</p><div class="detail-list"><div><small>Visit</small>${esc(j.date)} · ${esc(j.time)}</div><div><small>Status</small>${badge(j.status)}</div><div><small>Assigned crew</small>${esc(j.team)}</div>${field?'':`<div><small>Booking value</small>${money(j.amount)}</div>`}</div>${canManage?`<div class="form-grid" style="margin-top:24px"><label>Crew<select id="job-team">${options(['Unassigned','Team A · Ravi','Team B · Suresh','Team C · Mahesh','Team D · Deepak'],j.team)}</select></label><label>Date<input type="date" id="job-date" value="${esc(j.date)}" required></label><label>Time<input type="time" id="job-time" value="${esc(j.time)}" required></label><label>Status<select id="job-status">${options(['Scheduled','In progress','Completed'],j.status)}</select></label></div>`:''}${field?`<div class="checklist">${['Site preparation confirmed','Service checklist completed','Customer completion confirmation'].map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${j.checks.includes(i)?'checked':''}>${s}</label>`).join('')}</div><p class="sub">Completion requires all three checks.</p>`:''}</div>`,canManage?`<button class="primary" data-save-job="${id}">Save booking</button>`:field?`<button data-field-save="${id}">Save checklist</button><button class="primary" data-field-next="${id}" ${j.status==='Completed'?'disabled':''}>${j.status==='Scheduled'?'Start job':j.status==='Completed'?'Completed':'Complete job'}</button>`:'<button data-action="close">Close</button>')}
function invoice(id){let j=jobs().find(j=>j.id===id);if(!j)return;modal(`Invoice INV-${id}`,`<div class="modal-body"><p class="eyebrow">VU CARE SERVICES · DEMO INVOICE</p><h3>${esc(j.name)}</h3><p>${esc(j.service)} · ${esc(j.property)}<br>${esc(j.area)}, ${esc(j.city)}</p><div class="metric-row"><span>Service amount</span><b>${money(j.amount)}</b></div><div class="metric-row"><span>Paid</span><b>${money(j.paid)}</b></div><div class="metric-row"><span>Balance due</span><b>${money(j.amount-j.paid)}</b></div>${j.paid<j.amount?`<form id="pay-form" data-id="${id}"><div class="form-grid" style="margin-top:20px"><label>Payment amount (₹)<input name="amount" type="number" required min="1" max="${j.amount-j.paid}" value="${j.amount-j.paid}"></label><label>Method<select name="method">${options(['UPI','Bank transfer','Cash','Card'])}</select></label></div><p class="sub" style="margin:15px 0">Demo entry only. No money is charged.</p><button class="primary">Record payment</button></form>`:''}</div>`,'<button data-action="print">Print invoice</button>')}
function customerDetail(name){let c=customers().find(c=>c.name===name);if(!c)return;const history=db.jobs.filter(j=>j.name===name);modal(esc(c.name),`<div class="modal-body"><p>${esc(c.area)}, ${esc(c.city)}<br>${esc(c.property)}</p><h3>Service history</h3>${history.length?history.map(j=>`<div class="metric-row"><span>${esc(j.service)}<small style="display:block">${esc(j.date)}</small></span>${badge(j.status)}</div>`).join(''):'<p class="sub" style="margin-top:15px">Prospective customer · No completed bookings yet.</p>'}</div>`,'<button data-action="close">Close</button>')}
function ticketForm(){modal('New support request',`<form id="ticket-form"><div class="modal-body form-grid"><label class="full">Booking<select name="job">${db.jobs.map(j=>`<option value="${j.id}">VC-${j.id} · ${esc(j.name)}</option>`).join('')}</select></label><label class="full">Request<textarea name="issue" required maxlength="300" rows="3"></textarea></label><label>Priority<select name="priority">${options(['Low','Medium','High'])}</select></label></div><div class="modal-footer"><button class="primary">Create request</button></div></form>`)}
function exportCSV(){const rows=[['Booking','Customer','City','Service','Date','Status','Amount','Paid'],...jobs().map(j=>[j.id,j.name,j.city,j.service,j.date,j.status,j.amount,j.paid])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='vu-care-demo-bookings.csv';a.click();URL.revokeObjectURL(u);toast('Booking report exported')}
document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-lead]');if(!el)return;const d=el.dataset;if(d.nav){e.preventDefault();go(d.nav)}if(d.action==='close')$('#dialog').close();if(d.action==='new-lead')newLead();if(d.action==='new-ticket')ticketForm();if(d.action==='print')window.print();if(d.action==='export')exportCSV();if(d.lead)leadDetail(+d.lead);if(d.job)jobDetail(+d.job);if(d.invoice)invoice(+d.invoice);if(d.customer)customerDetail(d.customer);if(d.saveLead){db.leads.find(l=>l.id===+d.saveLead).status=$('#lead-stage').value;$('#dialog').close();save('Lead stage updated')}if(d.convert){const l=leads().find(l=>l.id===+d.convert);if(!l||l.status==='Converted')return;l.status='Converted';db.jobs.push({...l,id:Math.max(...db.jobs.map(j=>j.id))+1,paid:0,status:'Scheduled',team:'Unassigned',date:'2026-09-14',time:'09:00',checks:[]});$('#dialog').close();save(`${l.name} converted to a booking`);go('bookings')}if(d.saveJob){const j=jobs().find(j=>j.id===+d.saveJob);if(!$('#job-date').value||!$('#job-time').value)return toast('Choose a visit date and time');Object.assign(j,{team:$('#job-team').value,date:$('#job-date').value,time:$('#job-time').value,status:$('#job-status').value});$('#dialog').close();save('Booking and crew assignment updated')}if(d.fieldSave||d.fieldNext){const j=jobs().find(j=>j.id===+(d.fieldSave||d.fieldNext));j.checks=[...document.querySelectorAll('[data-check]:checked')].map(c=>+c.dataset.check);if(d.fieldNext){if(j.status==='Scheduled')j.status='In progress';else if(j.checks.length===3)j.status='Completed';else return toast('Complete all three checks before closing this job')}$('#dialog').close();save('Job progress saved')}if(d.ticket){const t=db.tickets.find(t=>t.id===+d.ticket);t.status=t.status==='Open'?'In progress':'Resolved';save('Support request updated')}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='lead-form'){if(!values.name.trim()||!values.area.trim())return toast('Enter a customer name and area');db.leads.unshift({...values,name:values.name.trim(),amount:Number(values.amount),id:Date.now(),status:'New enquiry',owner:'Ananya'});$('#dialog').close();page='leads';save(`${values.name} added as a new enquiry`)}if(f.id==='pay-form'){const j=jobs().find(j=>j.id===+f.dataset.id),n=Number(values.amount);if(!Number.isFinite(n)||n<=0||n>j.amount-j.paid)return toast('Enter an amount within the outstanding balance');j.paid+=n;$('#dialog').close();save(`${money(n)} payment recorded for ${j.name}`)}if(f.id==='ticket-form'){const j=db.jobs.find(j=>j.id===+values.job);if(!values.issue.trim())return;db.tickets.unshift({id:Date.now(),name:j.name,job:j.id,issue:values.issue,priority:values.priority,status:'Open'});$('#dialog').close();save('Support request created')}});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;city='All cities';query='';$('#dialog').close();render()}if(e.target.id==='city'){city=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const p=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(p,p)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-lead]')){e.preventDefault();leadDetail(+e.target.dataset.lead)}});
$('#menu').onclick=()=>document.body.classList.toggle('nav-open');$('#reset').onclick=()=>modal('Reset the demo?',`<div class="modal-body"><p>This restores the original fictional records and removes your changes in this browser.</p></div>`,'<button data-action="close">Cancel</button><button class="primary" id="confirm-reset">Reset demo</button>');document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){db=structuredClone(seed);$('#dialog').close();save('Demo data restored')}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(access[role].includes(p)&&p!==page){page=p;query='';render()}});if(access[role].includes(location.hash.slice(1)))page=location.hash.slice(1);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_crm_view',description:'Navigate to a CRM view available to the selected demo role.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(names)}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!access[role].includes(input.view))throw Error('View unavailable for this role');go(input.view);return {view:page,role}}})).catch(()=>{});}catch{}}

